mapper.select:
select ipm.project_type_code, ipm.project_type, ipm.project_define, ipm.project_define_code, ipm.wbs_code, ipm.wbs_name, ipm.project_unit_code, ipm.project_unit_name, ipm.loevm, ipm.project_create_time, (select count(*) from idevelop_project_manager_detail ipmd where ipmd.is_deleted = 0 and ipmd.wbs_code = ipm.wbs_code and ipmd.wbs_name = ipm.wbs_name) as erpTotal, id.region_code FROM idevelop_project_manager ipm left join (SELECT region_code,erp_unit_code,type from idevelop_dept WHERE type = 'CORP' and is_deleted = 0 GROUP BY erp_unit_code) id on ipm.project_unit_code = id.erp_unit_code where ipm.is_deleted = 0 and ipm.loevm = 'Y'
and ipm.wbs_code like concat('%', #{param2.wbsCode},'%')
and ipm.project_define_code like concat('%', #{param2.projectDefineCode},'%')
and ipm.project_define like concat('%', #{param2.projectDefine},'%')
and ipm.wbs_name like concat('%', #{param2.wbsName},'%')
and id.region_code like concat(#{param2.regionCode},'%')
and ipm.id IN
#{item}
and ipm.project_create_time >= #{param2.startTime}
and ipm.project_create_time <= #{param2.endTime}

select erp.* from ( select idrl.id as id, idrl.erp_asset_code as erpAssetCode, idrl.erp_account_code as erpAccountCode, idrl.erp_asset_status as erpAssetStatus, idrl.erp_status as erpStatus, idrl.i6000_status as i6000Status, idrl.device_code as deviceCode, idrl.device_name as deviceName, idrl.device_type as deviceType from idevelop_device_record_list idrl where is_deleted = 0 and idrl.erp_asset_code is not null
and idrl.wbs_project = #{wbsProject}
and idrl.wbs_element = #{wbsElement}
and idrl.erp_asset_code like concat('%', #{erpAssetCode},'%')
and idrl.erp_asset_status = #{erpAssetStatus}
and idrl.erp_status = #{erpStatus}
and idrl.i6000_status = #{i6000Status}
and idrl.device_code like concat('%', #{deviceCode},'%')
UNION ALL select idtd.id as id, idtd.erp_asset_code as erpAssetCode, idtd.erp_account_code as erpAccountCode, idtd.erp_asset_status as erpAssetStatus, idtd.erp_status as erpStatus, idtd.i6000_status as i6000Status, idtd.device_code as deviceCode, idtd.device_name as deviceName, idtd.device_type as deviceType from idevelop_device_transfer_detail idtd where is_deleted = 0 and idtd.erp_asset_code is not null
and idtd.wbs_project = #{wbsProject}
and idtd.wbs_element = #{wbsElement}
and idtd.erp_asset_code concat('%', #{erpAssetCode},'%')
and idtd.erp_asset_status = #{erpAssetStatus}
and idtd.erp_status = #{erpStatus}
and idtd.i6000_status = #{i6000Status}
and idtd.device_code like concat('%', #{deviceCode},'%')
) erp LIMIT #{current}, #{size}

select count(*) from ( select idrl.id as id, idrl.erp_asset_code as erpAssetCode, idrl.erp_account_code as erpAccountCode, idrl.erp_asset_status as erpAssetStatus, idrl.erp_status as erpStatus, idrl.i6000_status as i6000Status, idrl.device_code as deviceCode, idrl.device_name as deviceName, idrl.device_type as deviceType from idevelop_device_record_list idrl where is_deleted = 0 and idrl.erp_asset_code is not null
and idrl.wbs_project = #{wbsProject}
and idrl.wbs_element = #{wbsElement}
and idrl.erp_asset_code like concat('%', #{erpAssetCode},'%')
and idrl.erp_asset_status = #{erpAssetStatus}
and idrl.erp_status = #{erpStatus}
and idrl.i6000_status = #{i6000Status}
and idrl.device_code like concat('%', #{deviceCode},'%')
UNION ALL select idtd.id as id, idtd.erp_asset_code as erpAssetCode, idtd.erp_account_code as erpAccountCode, idtd.erp_asset_status as erpAssetStatus, idtd.erp_status as erpStatus, idtd.i6000_status as i6000Status, idtd.device_code as deviceCode, idtd.device_name as deviceName, idtd.device_type as deviceType from idevelop_device_transfer_detail idtd where is_deleted = 0 and idtd.erp_asset_code is not null
and idtd.wbs_project = #{wbsProject}
and idtd.wbs_element = #{wbsElement}
and idtd.erp_asset_code concat('%', #{erpAssetCode},'%')
and idtd.erp_asset_status = #{erpAssetStatus}
and idtd.erp_status = #{erpStatus}
and idtd.i6000_status = #{i6000Status}
and idtd.device_code like concat('%', #{deviceCode},'%')
) erp
